widget.solution:
import numpy as np
import pandas as pd

def best_weight(sig_a, sig_b, fwd, grid, split_date):
    before = sig_a.index < pd.Timestamp(split_date)
    def ic(w, rows):
        c = combine([sig_a, sig_b], [w, 1 - w])
        return rank_ic(c[rows], fwd[rows]).mean()
    scores = [ic(w, before) for w in grid]
    w = grid[int(np.argmax(scores))]
    return (round(float(w), 4), round(float(ic(w, before)), 4),
            round(float(ic(w, ~before)), 4))
